def find_path(graph, start, goal):
    # Initialize the stack for breadth-first search
    stack = [(start, [start])]

    while stack:
        (node, path) = stack.pop()
        for next_node in set(graph[node] + graph.keys() - set(path)) - {goal}:
            if next_node == goal:
                return path + [goal]
            stack.append((next_node, path + [next_node]))

    # If we reach here, the goal is not reachable
    return None
