def find_path(graph, start, goal):
    """
    Finds a path from start to goal in the graph using Depth-First Search (DFS)
    and returns it as a list of nodes. If the goal is not reachable, it returns None.
    """
    visited = set()
    path = []

    def dfs(node, goal):
        if node in visited:
            return None
        if node == goal:
            return [node]
        visited.add(node)
        for neighbor in graph[node]:
            new_path = dfs(neighbor, goal)
            if new_path:
                return [node] + new_path
        return None

    return dfs(start, goal)
