def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Initialize the queue with tuples (current node, path taken to reach this node)
    queue = [(start, [start])]
    visited = set()

    while queue:
        (current, path) = queue.pop(0)
        visited.add(current)

        for neighbor in graph[current]:
            if neighbor not in visited:
                if neighbor == goal:
                    return path + [neighbor]
                queue.append((neighbor, path + [neighbor]))
                visited.add(neighbor)

    # If we have exhausted all possible paths and haven't found the goal
    return None
