def find_path(graph, start, goal):
    # Initialize the path and the visited set
    path = []
    visited = set()

    def search(node):
        if node == goal:
            return True
        if node in visited:
            return False
        visited.add(node)
        path.append(node)
        for neighbor in graph.get(node, []):
            if search(neighbor):
                return True
        path.pop()
        return False

    if start not in graph:
        return None

    if search(start):
        return path
    else:
        return None
