    # Initialize the visited dictionary to keep track of visited nodes
    visited = {}

    # Initialize the path stack with the starting node
    path_stack = [(start, [start])]

    # Loop until we find the goal or exhaust all possibilities
    while path_stack:
        current_node, path = path_stack.pop()
        if current_node not in visited:
            visited[current_node] = True
            if current_node == goal:
                return path
            # Explore each neighbor of the current node
            for neighbor in graph.get(current_node, []):
                path_stack.append((neighbor, path + [neighbor]))
    # If the goal is unreachable, return None
    return None
